import { gsap } from 'gsap';

export default class Curseur {
  constructor(element) {
    this.element = element;
    this.options = {
      vitesseMax: 60,
      etirement: 0.6,
    };
    this.rond = this.element.querySelector('.curseur__rond');
    this.souris = { x: 0, y: 0 };
    this.avant = { x: 0, y: 0 };
    this.init();
  }

  init() {
    const aUneSouris = window.matchMedia('(pointer: fine)').matches;

    if (!aUneSouris) {
      this.element.remove();
      return;
    }

    this.setX = gsap.quickSetter(this.element, 'x', 'px');
    this.setY = gsap.quickSetter(this.element, 'y', 'px');
    this.setRotation = gsap.quickSetter(this.rond, 'rotation', 'deg');
    this.scaleX = gsap.quickTo(this.rond, 'scaleX', {
      duration: 0.6,
      ease: 'elastic.out(1, 0.3)',
    });
    this.scaleY = gsap.quickTo(this.rond, 'scaleY', {
      duration: 0.6,
      ease: 'elastic.out(1, 0.3)',
    });

    document.documentElement.classList.add('has-curseur');

    window.addEventListener('mousemove', this.onMove.bind(this));
    document.addEventListener('mousedown', this.onDown.bind(this));
    document.addEventListener('mouseup', this.onUp.bind(this));
    document.documentElement.addEventListener(
      'mouseleave',
      this.onLeave.bind(this),
    );

    const moinsAnimations = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches;
    if (!moinsAnimations) {
      gsap.ticker.add(this.onTick.bind(this));
    }
  }

  onMove(event) {
    this.souris.x = event.clientX;
    this.souris.y = event.clientY;

    this.setX(this.souris.x);
    this.setY(this.souris.y);
    this.element.classList.add('is-visible');
  }

  onTick() {
    const dx = this.souris.x - this.avant.x;
    const dy = this.souris.y - this.avant.y;
    this.avant.x = this.souris.x;
    this.avant.y = this.souris.y;

    const vitesse = Math.min(Math.hypot(dx, dy), this.options.vitesseMax);
    const etirement =
      (vitesse / this.options.vitesseMax) * this.options.etirement;

    if (vitesse > 1) {
      this.setRotation((Math.atan2(dy, dx) * 180) / Math.PI);
    }

    this.scaleX(1 + etirement);
    this.scaleY(1 - etirement / 2);
  }

  onDown() {
    this.element.classList.add('is-clic');
  }

  onUp() {
    this.element.classList.remove('is-clic');
  }

  onLeave() {
    this.element.classList.remove('is-visible');
  }
}
