import { gsap } from 'gsap';

export default class Intro {
  constructor(element) {
    this.element = element;
    this.options = {
      vitesse: 1,
      glissement: 40,
      attenteVideo: 2500,
    };
    this.html = document.documentElement;
    this.pret = false;
    this.lance = false;

    this.init();
  }

  init() {
    this.setOptions();

    // déjà vue pendant cette visite (ou animations réduites) : voir _header.html
    if (!this.html.classList.contains('intro-ouverte')) {
      this.element.remove();
      return;
    }

    this.hub = document.querySelector('.hub');
    this.rec = this.element.querySelector('.js-rec');
    this.disque = this.element.querySelector('.js-disque');
    this.textes = this.element.querySelectorAll('.js-texte');
    this.interface = this.element.querySelector('.js-interface');
    this.haut = this.element.querySelector('.js-haut');
    this.cadre = this.element.querySelector('.js-cadre');
    this.voile = this.element.querySelector('.js-voile');
    this.enregistrement = this.element.querySelector('.js-enregistrement');
    this.coins = this.element.querySelectorAll('.js-coin');
    this.bas = this.element.querySelector('.js-bas');
    this.etat = this.element.querySelector('.js-etat');
    this.lut = this.element.querySelector('.js-lut');
    this.flash = this.element.querySelector('.js-flash');
    this.volets = this.element.querySelectorAll('.js-volet');
    this.trait = this.element.querySelector('.js-trait');
    this.journal = this.element.querySelector('.js-journal');
    this.signal = this.element.querySelector('.js-signal');

    this.initObjectif();
    this.initMiseAuPoint();
    this.initEcouteurs();
    this.initHorloge();
    this.bloquerPage();
    this.placerBas();
    this.element.focus({ preventScroll: true }); // le focus sur REC l'afficherait déjà en survol

    this.demarrer();
  }

  setOptions() {
    if ('vitesse' in this.element.dataset) {
      this.options.vitesse = parseFloat(this.element.dataset.vitesse);
    }
  }

  // image de la caméra en WebGL ; sinon, simple flou CSS par-dessus le hub
  initObjectif() {
    this.objectif = new Objectif(this.element.querySelector('.js-objectif'));
    this.reglages = this.objectif.reglages;

    if (!this.objectif.actif) {
      this.element.classList.add('is-sans-objectif');
      this.objectif.element.remove();
    }
  }

  initEcouteurs() {
    this.onTouche = this.onTouche.bind(this);
    this.onRoulette = this.onRoulette.bind(this);
    this.onDoigtDebut = this.onDoigtDebut.bind(this);
    this.onDoigtBouge = this.onDoigtBouge.bind(this);
    this.onPointeur = this.onPointeur.bind(this);
    this.placerBas = this.placerBas.bind(this);
    this.onTick = this.onTick.bind(this);

    this.rec.addEventListener('click', this.lancer.bind(this));
    this.rec.addEventListener('pointerenter', this.verrouiller.bind(this));
    this.rec.addEventListener('pointerleave', this.deverrouiller.bind(this));
    document.addEventListener('keydown', this.onTouche);
    window.addEventListener('wheel', this.onRoulette, { passive: true });
    window.addEventListener('touchstart', this.onDoigtDebut, { passive: true });
    window.addEventListener('touchmove', this.onDoigtBouge, { passive: true });
    window.addEventListener('pointermove', this.onPointeur);
    window.addEventListener('pointerdown', this.onPointeur);
    window.addEventListener('resize', this.placerBas);
    gsap.ticker.add(this.onTick);
  }

  //Page en attente

  // le reste de la page est inaccessible au clavier pendant l'intro
  bloquerPage() {
    this.inertes = [];
    const enfants = document.body.children;

    for (let i = 0; i < enfants.length; i++) {
      if (enfants[i] !== this.element && !enfants[i].inert) {
        enfants[i].inert = true;
        this.inertes.push(enfants[i]);
      }
    }
  }

  debloquerPage() {
    for (let i = 0; i < this.inertes.length; i++) {
      this.inertes[i].inert = false;
    }
  }

  // la barre du bas se place exactement sur celle du hub pour que le relais soit invisible
  placerBas() {
    const cible = this.hub.querySelector('.bottom').getBoundingClientRect();
    this.aligne = cible.bottom <= this.element.clientHeight;

    if (this.aligne) {
      gsap.set(this.bas, {
        top: cible.top,
        left: cible.left,
        width: cible.width,
        right: 'auto',
        bottom: 'auto',
      });
    } else {
      gsap.set(this.bas, { clearProps: 'top,left,width,right,bottom' });
    }
  }

  initHorloge() {
    this.date = this.element.querySelector('.js-date');
    this.heure = this.element.querySelector('.js-heure');
    this.mettreHeure();
    this.horloge = setInterval(this.mettreHeure.bind(this), 1000);
  }

  mettreHeure() {
    const maintenant = new Date();
    const deux = (nombre) => String(nombre).padStart(2, '0');

    this.date.textContent = [
      deux(maintenant.getDate()),
      deux(maintenant.getMonth() + 1),
      String(maintenant.getFullYear()).slice(2),
    ].join('.');
    this.heure.textContent = [
      deux(maintenant.getHours()),
      deux(maintenant.getMinutes()),
      deux(maintenant.getSeconds()),
    ].join(':');
  }

  //Démarrage de la caméra

  demarrer() {
    const entrees = this.journal.querySelectorAll('.js-entree');
    const journal = gsap.timeline();

    // le journal s'écrit ligne par ligne
    for (let i = 0; i < entrees.length; i++) {
      journal.to(
        entrees[i],
        { clipPath: 'inset(0 0% 0 0)', duration: 0.24, ease: 'steps(20)' },
        0.15 + i * 0.16,
      );
    }

    journal.add(() => {
      this.attendreVideo().then(this.allumer.bind(this));
    });
  }

  // la dernière ligne attend que la vidéo du hub soit prête (au plus quelques secondes)
  attendreVideo() {
    return new Promise((resolve) => {
      const video = this.hub.querySelector('video');
      let fait = false;

      const fin = () => {
        if (fait) return;
        fait = true;
        this.signal.textContent = 'OK';
        this.signal.classList.add('is-ok');
        setTimeout(resolve, 280);
      };

      if (!video || video.readyState >= 3) {
        fin();
        return;
      }

      video.addEventListener('canplay', fin, { once: true });
      setTimeout(fin, this.options.attenteVideo);
    });
  }

  // l'écran s'allume comme un vieux moniteur, puis l'interface se monte
  allumer() {
    const timeline = gsap.timeline({
      onComplete: () => {
        this.pret = true;
      },
    });

    timeline
      .to(this.journal, { autoAlpha: 0, duration: 0.25 }, 0)
      .fromTo(
        this.trait,
        { scaleX: 0 },
        { scaleX: 1, duration: 0.4, ease: 'expo.out' },
        0.1,
      )
      .to(this.volets[0], { yPercent: -100, duration: 0.8, ease: 'expo.inOut' }, 0.42)
      .to(this.volets[1], { yPercent: 100, duration: 0.8, ease: 'expo.inOut' }, 0.42)
      .to(this.trait, { scaleY: 0, opacity: 0, duration: 0.35 }, 0.6)
      .fromTo(
        this.reglages,
        { lumiere: 1.7 },
        { lumiere: 0.85, duration: 1, ease: 'power2.out' },
        0.5,
      );

    timeline
      .from(
        this.coins,
        {
          x: (i) => [60, -60, 60, -60][i],
          y: (i) => [40, 40, -40, -40][i],
          opacity: 0,
          duration: 1,
          ease: 'expo.out',
        },
        0.75,
      )
      .from(this.cadre, { opacity: 0, scale: 0.94, duration: 1, ease: 'expo.out' }, 0.8)
      .from(this.haut, { opacity: 0, y: -14, duration: 0.7, ease: 'power3.out' }, 0.9)
      .from(this.bas, { opacity: 0, y: 14, duration: 0.7, ease: 'power3.out' }, 0.9)
      .from(this.rec, { opacity: 0, scale: 0.5, duration: 0.9, ease: 'back.out(1.7)' }, 0.95)
      .from(
        [this.textes[0], this.textes[3]],
        { opacity: 0, y: 12, duration: 0.7, stagger: 0.1, ease: 'power3.out' },
        1.1,
      );

    timeline.timeScale(this.options.vitesse);
  }

  //Mise au point

  // la zone nette de l'image suit le pointeur
  initMiseAuPoint() {
    this.sourisFine = window.matchMedia('(pointer: fine)').matches;
    this.dernierPointeur = 0;
    this.verrou = false;

    this.viserX = gsap.quickTo(this.reglages, 'focusX', {
      duration: 0.7,
      ease: 'power3',
    });
    this.viserY = gsap.quickTo(this.reglages, 'focusY', {
      duration: 0.7,
      ease: 'power3',
    });
  }

  onPointeur(event) {
    if (this.lance || this.verrou) return;
    if (event.type === 'pointermove' && event.pointerType !== 'mouse') return;

    this.dernierPointeur = performance.now();
    this.viserX(event.clientX);
    this.viserY(event.clientY);
  }

  // survol du bouton REC : la mise au point se verrouille dessus et l'image s'assombrit autour
  verrouiller() {
    if (this.lance) return;

    const bouton = this.rec.getBoundingClientRect();
    this.verrou = true;
    this.viserX(bouton.left + bouton.width / 2);
    this.viserY(bouton.top + bouton.height / 2);

    if (this.pret) {
      gsap.to(this.reglages, { lumiere: 0.55, zone: 80, duration: 0.6, ease: 'power3.out' });
    }
  }

  deverrouiller() {
    this.verrou = false;

    if (this.pret && !this.lance) {
      gsap.to(this.reglages, { lumiere: 0.85, zone: 150, duration: 0.6, ease: 'power3.out' });
    }
  }

  onTick(temps) {
    const r = this.reglages;

    // au doigt, sans geste depuis un moment : la caméra cherche son sujet toute seule
    const inactif = performance.now() - this.dernierPointeur > 2500;
    if (!this.sourisFine && inactif && !this.verrou && !this.lance) {
      this.viserX(this.element.clientWidth * (0.5 + Math.cos(temps * 0.4) * 0.32));
      this.viserY(this.element.clientHeight * (0.5 + Math.sin(temps * 0.4) * 0.26));
    }

    // sans WebGL : le flou CSS suit les mêmes réglages
    if (!this.objectif.actif) {
      this.element.style.setProperty('--flou', `${r.flou * (1 - r.net) * 0.5}px`);
      this.element.style.setProperty('--lumiere', Math.min(r.lumiere, 1));
    }
  }

  onTouche(event) {
    if (event.key === 'Escape') this.passer();
    if (event.key === 'Enter') this.lancer();
  }

  onRoulette(event) {
    if (event.deltaY > 0) this.lancer();
  }

  onDoigtDebut(event) {
    this.doigtY = event.touches[0].clientY;
  }

  onDoigtBouge(event) {
    if (this.doigtY - event.touches[0].clientY > this.options.glissement) {
      this.lancer();
    }
  }

  //REC

  lancer() {
    if (!this.pret || this.lance) return;
    this.lance = true;
    this.element.classList.add('is-lance');
    this.verrou = false;
    gsap.killTweensOf(this.reglages, 'lumiere,zone');
    this.demarrerTimecodes();

    const vol = this.calculerVol();
    const coins = this.calculerCoins();
    const r = this.reglages;
    const timeline = gsap.timeline({ onComplete: this.terminer.bind(this) });

    // le bouton s'enfonce, le cadre rouge d'enregistrement s'allume
    timeline
      .to(this.disque, { scale: 0.82, duration: 0.12, ease: 'power2.out' }, 0)
      .to(this.textes, { opacity: 0, duration: 0.25, ease: 'power1.out' }, 0.05)
      .fromTo(
        this.enregistrement,
        { opacity: 0, scale: 1.04 },
        { opacity: 1, scale: 1, duration: 0.4, ease: 'expo.out' },
        0.05,
      );

    // le disque rouge devient le point REC de la barre du bas
    timeline
      .to(
        this.disque,
        { x: vol.x, y: vol.y, scale: vol.scale, duration: 0.6, ease: 'expo.inOut' },
        0.15,
      )
      .add(this.allumerRec.bind(this), 0.75);

    // mise au point complète (elle cherche un peu) et application du LUT rouge
    timeline
      .to(r, { net: 0.6, duration: 0.25, ease: 'power2.out' }, 0.2)
      .to(r, { net: 0.35, duration: 0.2, ease: 'power1.inOut' }, 0.45)
      .to(r, { net: 1, duration: 0.45, ease: 'power3.out' }, 0.65)
      .to(r, { lut: 1, lumiere: 1, aberration: 2, duration: 0.8, ease: 'power2.inOut' }, 0.3)
      .to(this.voile, { opacity: 0.45, duration: 0.8 }, 0.3)
      .add(() => {
        this.lut.textContent = 'ML_Rouge.cube';
      }, 0.55);

    // les coins du viseur se referment sur le titre
    for (let i = 0; i < this.coins.length; i++) {
      timeline.to(
        this.coins[i],
        { ...coins[i], duration: 0.8, ease: 'expo.inOut' },
        0.35,
      );
    }
    timeline.to([this.coins[1], this.coins[3]], { opacity: 0, duration: 0.3 }, 1.15);

    // plongée dans l'objectif
    timeline
      .to(
        r,
        { zoom: 1.9, distorsion: 0.6, aberration: 18, derive: 0, duration: 0.6, ease: 'power3.in' },
        1.15,
      )
      .to(this.interface, { scale: 1.5, opacity: 0, duration: 0.55, ease: 'power2.in' }, 1.15)
      .to(this.enregistrement, { scale: 1.06, opacity: 0, duration: 0.5, ease: 'power2.in' }, 1.25);

    // flash, puis le site
    timeline
      .to(this.flash, { opacity: 0.6, duration: 0.07, ease: 'none' }, 1.72)
      .add(this.relacher.bind(this), 1.79)
      .to(this.flash, { opacity: 0, duration: 0.5, ease: 'power2.out' }, 1.79);

    timeline.timeScale(this.options.vitesse);
  }

  // tous les timecodes repartent de 00:00:00 au même moment (voir Timecode.js)
  demarrerTimecodes() {
    document.dispatchEvent(
      new CustomEvent('intro:rec', { detail: { debut: performance.now() } }),
    );
  }

  calculerVol() {
    const depart = this.disque.getBoundingClientRect();
    const arrivee = this.etat.getBoundingClientRect();
    const point = parseFloat(getComputedStyle(this.etat, '::before').width);

    return {
      x: arrivee.left + point / 2 - (depart.left + depart.width / 2),
      y: arrivee.top + arrivee.height / 2 - (depart.top + depart.height / 2),
      scale: point / depart.width,
    };
  }

  // positions des coins du hero (haut gauche, haut droit, bas gauche, bas droit)
  calculerCoins() {
    const texte = this.hub.querySelector('.texte');
    const cible = texte.getBoundingClientRect();
    const taille = parseFloat(getComputedStyle(texte, '::before').width);
    const droite = this.element.clientWidth - cible.right;
    const bas = this.element.clientHeight - cible.bottom;

    return [
      { top: cible.top, left: cible.left, width: taille, height: taille },
      { top: cible.top, right: droite, width: taille, height: taille },
      { bottom: bas, left: cible.left, width: taille, height: taille },
      { bottom: bas, right: droite, width: taille, height: taille },
    ];
  }

  allumerRec() {
    this.etat.classList.remove('is-standby');
    this.etat.textContent = 'REC 1080p';
    gsap.set(this.disque, { autoAlpha: 0 });
  }

  // le générique du hub démarre ; ses coins et sa barre du bas remplacent ceux de l'intro
  relacher() {
    this.html.classList.remove('intro-attente');
    this.objectif.detruire();
    gsap.set([this.objectif.element, this.voile, this.coins[0], this.coins[2]], {
      autoAlpha: 0,
    });
    gsap.set(this.element, { backgroundColor: 'transparent' });

    if (this.aligne) {
      gsap.set(this.bas, { autoAlpha: 0 });
    } else {
      gsap.to(this.bas, { autoAlpha: 0, duration: 0.4 });
    }
  }

  //Échap

  passer() {
    if (this.lance) return;
    this.lance = true;
    this.element.classList.add('is-lance');
    this.demarrerTimecodes();
    this.html.classList.remove('intro-attente');

    gsap.to(this.element, {
      opacity: 0,
      duration: 0.4,
      ease: 'power2.out',
      onComplete: this.terminer.bind(this),
    });
  }

  //Fin

  terminer() {
    const header = document.querySelector('.header');

    gsap.set(header, { opacity: 0 });
    this.html.classList.remove('intro-ouverte', 'intro-attente');
    gsap.to(header, {
      opacity: 1,
      duration: 0.6,
      ease: 'power1.out',
      clearProps: 'opacity',
    });

    this.objectif.detruire();
    this.debloquerPage();
    clearInterval(this.horloge);
    gsap.ticker.remove(this.onTick);
    document.removeEventListener('keydown', this.onTouche);
    window.removeEventListener('wheel', this.onRoulette);
    window.removeEventListener('touchstart', this.onDoigtDebut);
    window.removeEventListener('touchmove', this.onDoigtBouge);
    window.removeEventListener('pointermove', this.onPointeur);
    window.removeEventListener('pointerdown', this.onPointeur);
    window.removeEventListener('resize', this.placerBas);

    this.element.remove();
  }
}

//Objectif : l'image de la caméra, la vidéo du hub vue à travers un objectif (WebGL 2)
// Intro anime les valeurs de this.reglages

const vert = `#version 300 es
in vec2 position;
out vec2 vUv;
void main(){
  vUv = position * 0.5 + 0.5;
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

const frag = `#version 300 es
precision highp float;
uniform sampler2D uVideo;
uniform vec2 uResolution;
uniform vec2 uVideoSize;
uniform vec2 uFocus;
uniform float uZone;
uniform float uFlou;
uniform float uNet;
uniform float uLut;
uniform float uAberration;
uniform float uDistorsion;
uniform float uZoom;
uniform float uDerive;
uniform float uGrain;
uniform float uLumiere;
uniform float uTemps;
in vec2 vUv;
out vec4 fragColor;

const vec3 ROUGE_A = vec3(0.290, 0.075, 0.043);
const vec3 ROUGE_B = vec3(0.141, 0.039, 0.024);
const vec3 FOND = vec3(0.055, 0.043, 0.039);
const vec3 TEINTE = vec3(0.478, 0.122, 0.071);
const float ANGLE_OR = 2.39996323;
const int TAPS = 24;

// point de l'écran (px, y vers le bas) → couleur de la vidéo, cadrée comme object-fit: cover
vec3 video(vec2 p, float lod) {
  float echelle = max(uResolution.x / uVideoSize.x, uResolution.y / uVideoSize.y);
  vec2 taille = uVideoSize * echelle;
  vec2 uv = (p - (uResolution - taille) * 0.5) / taille;
  return textureLod(uVideo, clamp(uv, 0.0, 1.0), lod).rgb;
}

float luminance(vec3 c) {
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

// image « log » plate de la caméra → étalonnage rouge du hub (même recette que hub.scss)
vec3 etalonner(vec3 c, vec2 p) {
  float l = luminance(c);
  vec3 plat = mix(vec3(l), c, 0.3) * vec3(1.04, 1.0, 0.94);
  plat = plat * 0.7 + 0.1;

  float t = dot(p - uResolution * 0.5, vec2(0.70710678)) / ((uResolution.x + uResolution.y) * 0.70710678) + 0.5;
  vec3 degrade = t < 0.6 ? mix(ROUGE_A, ROUGE_B, t / 0.6) : mix(ROUGE_B, FOND, (t - 0.6) / 0.4);
  float gris = clamp((l - 0.5) * 1.1 + 0.5, 0.0, 1.0);
  vec3 rouge = mix(degrade, vec3(gris), 0.7) * TEINTE;

  return mix(plat, rouge, uLut);
}

void main() {
  vec2 p = vec2(vUv.x, 1.0 - vUv.y) * uResolution;
  vec2 centre = uResolution * 0.5;
  vec2 d = (p - centre) / uResolution.y;

  // objectif : zoom, distorsion en barillet et léger bougé à l'épaule
  vec2 q = centre + (p - centre) * (1.0 + uDistorsion * dot(d, d)) / uZoom;
  q += vec2(
    sin(uTemps * 0.7) * 0.6 + sin(uTemps * 1.31) * 0.4,
    cos(uTemps * 0.83) * 0.5 + sin(uTemps * 1.67) * 0.3
  ) * uDerive;

  // mise au point : nette autour du point visé, de plus en plus floue en s'éloignant
  float ecart = length(p - uFocus);
  float rayon = uFlou * smoothstep(uZone * 0.3, uZone * 2.5, ecart) * (1.0 - uNet);

  // aberration chromatique : plus forte vers les bords
  vec2 ca = d * uAberration;
  vec3 couleur;

  if (rayon < 0.75) {
    vec3 c = video(q, 0.0);
    vec3 r = video(q + ca, 0.0);
    vec3 b = video(q - ca, 0.0);
    couleur = vec3(etalonner(r, p).r, etalonner(c, p).g, etalonner(b, p).b);
  } else {
    // bokeh : échantillons en spirale, les hautes lumières pèsent plus lourd
    float lod = log2(max(rayon / 5.0, 1.0));
    vec3 somme = vec3(0.0);
    float poids = 0.0;

    for (int i = 0; i < TAPS; i++) {
      float f = float(i) + 0.5;
      vec2 o = vec2(cos(f * ANGLE_OR), sin(f * ANGLE_OR)) * sqrt(f / float(TAPS)) * rayon;
      vec3 e = video(q + o, lod);
      float w = 1.0 + pow(luminance(e), 4.0) * 8.0;
      somme += e * w;
      poids += w;
    }

    vec3 c = somme / poids;
    vec3 r = mix(c, video(q + ca, lod + 1.0), 0.5);
    vec3 b = mix(c, video(q - ca, lod + 1.0), 0.5);
    couleur = vec3(etalonner(r, p).r, etalonner(c, p).g, etalonner(b, p).b);
  }

  // grain de pellicule
  float n = fract(sin(dot(p + fract(uTemps) * 517.0, vec2(12.9898, 78.233))) * 43758.5453);
  couleur += (n - 0.5) * uGrain;

  fragColor = vec4(couleur * uLumiere, 1.0);
}
`;

class Objectif {
  constructor(element) {
    this.element = element;
    this.options = {
      ratioMax: 1.25,
    };
    this.video = document.querySelector('.hub__media video');
    this.reglages = {
      flou: 28,
      zone: 150,
      net: 0,
      lut: 0,
      aberration: 3,
      distorsion: 0.06,
      zoom: 1.06,
      derive: 5,
      grain: 0.07,
      lumiere: 0.85,
      focusX: window.innerWidth / 2,
      focusY: window.innerHeight * 0.45,
    };
    this.actif = false;

    this.init();
  }

  init() {
    this.setOptions();

    this.gl = this.element.getContext('webgl2', {
      antialias: false,
      alpha: false,
    });
    if (!this.gl || !this.video) return;

    this.initProgramme();
    this.initTexture();

    this.onResize = this.onResize.bind(this);
    this.onResize();
    window.addEventListener('resize', this.onResize);

    this.render = this.render.bind(this);
    this.raf = requestAnimationFrame(this.render);
    this.actif = true;
  }

  setOptions() {
    if ('ratioMax' in this.element.dataset) {
      this.options.ratioMax = parseFloat(this.element.dataset.ratioMax);
    }
  }

  //WebGL

  initProgramme() {
    const gl = this.gl;
    const programme = gl.createProgram();
    gl.attachShader(programme, this.shader(gl.VERTEX_SHADER, vert));
    gl.attachShader(programme, this.shader(gl.FRAGMENT_SHADER, frag));
    gl.linkProgram(programme);
    gl.useProgram(programme);
    this.programme = programme;

    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(
      gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
      gl.STATIC_DRAW,
    );
    const position = gl.getAttribLocation(programme, 'position');
    gl.enableVertexAttribArray(position);
    gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

    const noms = [
      'uResolution',
      'uVideoSize',
      'uFocus',
      'uZone',
      'uFlou',
      'uNet',
      'uLut',
      'uAberration',
      'uDistorsion',
      'uZoom',
      'uDerive',
      'uGrain',
      'uLumiere',
      'uTemps',
    ];
    this.u = {};
    for (let i = 0; i < noms.length; i++) {
      this.u[noms[i]] = gl.getUniformLocation(programme, noms[i]);
    }
  }

  shader(type, source) {
    const gl = this.gl;
    const shader = gl.createShader(type);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      console.log(gl.getShaderInfoLog(shader));
    }
    return shader;
  }

  // texture noire d'un pixel en attendant la première image de la vidéo
  initTexture() {
    const gl = this.gl;
    this.texture = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, this.texture);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA,
      1,
      1,
      0,
      gl.RGBA,
      gl.UNSIGNED_BYTE,
      new Uint8Array([0, 0, 0, 255]),
    );
    gl.generateMipmap(gl.TEXTURE_2D);
    gl.uniform2f(this.u.uVideoSize, 1, 1);
  }

  onResize() {
    this.ratio = Math.min(window.devicePixelRatio || 1, this.options.ratioMax);
    this.element.width = this.element.clientWidth * this.ratio;
    this.element.height = this.element.clientHeight * this.ratio;
    this.gl.viewport(0, 0, this.element.width, this.element.height);
    this.gl.uniform2f(
      this.u.uResolution,
      this.element.width,
      this.element.height,
    );
  }

  render(temps) {
    const gl = this.gl;
    const r = this.reglages;

    if (this.video.readyState >= 2) {
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, this.video);
      gl.generateMipmap(gl.TEXTURE_2D);
      gl.uniform2f(this.u.uVideoSize, this.video.videoWidth, this.video.videoHeight);
    }

    gl.uniform2f(this.u.uFocus, r.focusX * this.ratio, r.focusY * this.ratio);
    gl.uniform1f(this.u.uZone, r.zone * this.ratio);
    gl.uniform1f(this.u.uFlou, r.flou * this.ratio);
    gl.uniform1f(this.u.uNet, r.net);
    gl.uniform1f(this.u.uLut, r.lut);
    gl.uniform1f(this.u.uAberration, r.aberration * this.ratio);
    gl.uniform1f(this.u.uDistorsion, r.distorsion);
    gl.uniform1f(this.u.uZoom, r.zoom);
    gl.uniform1f(this.u.uDerive, r.derive * this.ratio);
    gl.uniform1f(this.u.uGrain, r.grain);
    gl.uniform1f(this.u.uLumiere, r.lumiere);
    gl.uniform1f(this.u.uTemps, temps / 1000);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

    this.raf = requestAnimationFrame(this.render);
  }

  detruire() {
    if (!this.actif) return;
    this.actif = false;

    cancelAnimationFrame(this.raf);
    window.removeEventListener('resize', this.onResize);

    const perte = this.gl.getExtension('WEBGL_lose_context');
    if (perte) perte.loseContext();
  }
}
