import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger.js';

export default class PleinEcran {
  constructor(element) {
    gsap.registerPlugin(ScrollTrigger);
    this.element = element;
    this.options = {
      duree: 1.5,
    };
    this.wrapper = this.element.querySelector('.wrapper');
    this.video = this.element.querySelector('.video');

    this.init();
  }

  init() {
    this.setOptions();

    const moinsAnimations = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches;
    if (moinsAnimations) return;

    this.timeline = gsap.timeline({
      scrollTrigger: {
        trigger: this.element,
        start: 'top top',
        end: () => '+=' + window.innerHeight * this.options.duree,
        pin: true,
        anticipatePin: 1,
        scrub: true,
        invalidateOnRefresh: true,
      },
    });

    this.timeline.fromTo(
      this.video,
      {
        width: () => this.largeurDepart(),
        height: () => (this.largeurDepart() * 9) / 16,
        borderRadius: 4,
        borderColor: 'rgba(242, 233, 221, 0.1)',
      },
      {
        width: () => document.documentElement.clientWidth,
        height: () => this.hauteurFin(),
        borderRadius: 0,
        borderColor: 'rgba(242, 233, 221, 0)',
        ease: 'power2.inOut',
        duration: 1,
      },
    );

    this.timeline.to({}, { duration: 0.5 });
  }

  setOptions() {
    if ('duree' in this.element.dataset) {
      this.options.duree = parseFloat(this.element.dataset.duree);
    }
  }

  hauteurFin() {
    const largeur = document.documentElement.clientWidth;
    const hauteur = window.innerHeight;

    if (hauteur > largeur) {
      return (largeur * 9) / 16;
    }

    return hauteur;
  }

  largeurDepart() {
    const style = getComputedStyle(this.wrapper);
    return (
      this.wrapper.clientWidth -
      parseFloat(style.paddingLeft) -
      parseFloat(style.paddingRight)
    );
  }
}
