export default class YouTube {
  constructor(element) {
    this.element = element;
    this.videoContainer = this.element.querySelector('.js-video');
    this.lancer = this.element.querySelector('.js-lancer');
    this.videoId = this.element.dataset.videoId;
    this.playerReady = false;
    this.demande = false;

    YouTube.instances.push(this);

    if (this.videoId) {
      YouTube.loadScript();
    } else {
      console.log('Vous devez spécifier un ID');
    }

    if (this.lancer) {
      this.lancer.addEventListener('click', this.onLancer.bind(this));
    }
  }

  static loadScript() {
    if (!YouTube.scriptIsLoading) {
      YouTube.scriptIsLoading = true;

      const script = document.createElement('script');
      script.src = 'https://www.youtube.com/iframe_api';
      document.body.appendChild(script);
    }
  }

  init() {
    if (!this.lancer || this.demande) {
      this.initPlayer();
    }
  }

  //Lecture

  onLancer() {
    if (this.playerReady) {
      this.element.classList.add('is-lecture');
      this.player.playVideo();
      return;
    }

    this.demande = true;
    this.element.classList.add('is-chargement');

    if (YouTube.apiPrete) {
      this.initPlayer();
    }
  }

  initPlayer() {
    if (this.player) return;

    this.player = new YT.Player(this.videoContainer, {
      height: '100%',
      width: '100%',
      videoId: this.videoId,
      playerVars: { rel: 0, autoplay: this.demande ? 1 : 0, playsinline: 1 },
      events: {
        onReady: () => {
          this.playerReady = true;

          const observer = new IntersectionObserver(this.watch.bind(this));
          observer.observe(this.element);

          if (this.demande) {
            this.player.playVideo();
            this.element.classList.add('is-lecture');
            this.player.getIframe().focus();
          }
        },
        onStateChange: (event) => {
          if (event.data == YT.PlayerState.PLAYING) {
            this.element.classList.remove('is-chargement');
            YouTube.pauseAll(this);
          } else if (event.data == YT.PlayerState.ENDED) {
            this.player.seekTo(0);
            this.player.pauseVideo();
            this.element.classList.remove('is-lecture');
          }
        },
      },
    });
  }

  // met la vidéo en pause quand elle sort de l'écran
  watch(entries) {
    if (this.playerReady && !entries[0].isIntersecting) {
      this.player.pauseVideo();
    }
  }

  static initAll() {
    YouTube.apiPrete = true;
    document.documentElement.classList.add('is-video-ready');

    for (let i = 0; i < YouTube.instances.length; i++) {
      const instance = YouTube.instances[i];
      instance.init();
    }
  }

  static pauseAll(currentInstance) {
    for (let i = 0; i < YouTube.instances.length; i++) {
      const instance = YouTube.instances[i];
      if (instance.playerReady && instance !== currentInstance) {
        instance.player.pauseVideo();
      }
    }
  }
}

YouTube.instances = [];
window.onYouTubeIframeAPIReady = YouTube.initAll;
