import Header from './components/Header.js';
import Projets from './components/Projets.js';
import Scrolly from './components/Scrolly.js';
import Horiz from './components/Horiz.js';
import Curseur from './components/Curseur.js';
import GridScan from './components/GridScan.js';
import YouTube from './components/YouTube.js';
import Timecode from './components/Timecode.js';
import PleinEcran from './components/PleinEcran.js';
import Transition from './components/Transition.js';
import ChargementVideos from './components/ChargementVideos.js';
import CursorGrid from './components/CursorGrid.js';
import CopierCourriel from './components/CopierCourriel.js';
import Intro from './components/Intro.js';

export default class ComponentFactory {
  constructor() {
    this.componentInstances = [];
    this.componentList = {
      Header,
      Projets,
      Scrolly,
      Horiz,
      Curseur,
      GridScan,
      YouTube,
      Timecode,
      PleinEcran,
      Transition,
      ChargementVideos,
      CursorGrid,
      CopierCourriel,
      Intro,
    };
    this.init();
  }
  init() {
    const components = document.querySelectorAll('[data-component]');

    for (let i = 0; i < components.length; i++) {
      const element = components[i];
      const componentName = element.dataset.component;

      if (this.componentList[componentName]) {
        const instance = new this.componentList[componentName](element);
        this.componentInstances.push(instance);
      } else {
        console.log(`La composante ${componentName} n'existe pas`);
      }
    }
  }
}
