export default class ChargementVideos {
  constructor(element) {
    this.element = element;
    this.options = {
      marge: '100% 0px',
    };
    this.videos = this.element.querySelectorAll('video[data-src]');
    this.charge = false;
    this.enAttente = false;

    this.init();
  }

  init() {
    this.setOptions();
    this.lancer = this.lancer.bind(this);
    this.onGeste = this.onGeste.bind(this);

    this.observer = new IntersectionObserver(this.watch.bind(this), {
      rootMargin: this.options.marge,
    });
    for (let i = 0; i < this.videos.length; i++) {
      this.observer.observe(this.videos[i]);
    }

    window.addEventListener('pageshow', this.onPageShow.bind(this));
  }

  setOptions() {
    if ('marge' in this.element.dataset) {
      this.options.marge = this.element.dataset.marge;
    }
  }

  // chaque vidéo se charge quand elle approche de l'écran
  watch(entries) {
    for (let i = 0; i < entries.length; i++) {
      if (!entries[i].isIntersecting) continue;

      this.observer.unobserve(entries[i].target);
      this.charger(entries[i].target);
    }
  }

  charger(video) {
    if (video.dataset.poster) {
      video.poster = video.dataset.poster;
    }
    video.src = video.dataset.src;
    video.removeAttribute('data-src');
    video.load();

    this.charge = true;
    this.lancer();
  }

  lancer() {
    for (let i = 0; i < this.videos.length; i++) {
      if (!this.videos[i].getAttribute('src')) continue;

      const promesse = this.videos[i].play();

      if (promesse) {
        promesse.catch(this.attendreGeste.bind(this));
      }
    }
  }

  attendreGeste() {
    if (this.enAttente) return;
    this.enAttente = true;

    document.addEventListener('touchstart', this.onGeste, { passive: true });
    document.addEventListener('click', this.onGeste);
    document.addEventListener('keydown', this.onGeste);
  }

  onGeste() {
    this.enAttente = false;
    document.removeEventListener('touchstart', this.onGeste);
    document.removeEventListener('click', this.onGeste);
    document.removeEventListener('keydown', this.onGeste);

    this.lancer();
  }

  onPageShow(event) {
    if (event.persisted && this.charge) {
      this.lancer();
    }
  }
}
