export default class Transition {
  constructor(element) {
    this.element = element;
    this.options = {
      fermeture: 650,
      pause: 300,
      ouverture: 850,
    };
    this.html = document.documentElement;
    this.enCours = false;

    this.init();
  }

  init() {
    this.setOptions();

    this.moinsAnimations = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches;
    if (this.moinsAnimations) return;

    document.addEventListener('click', this.onClick.bind(this));
    window.addEventListener('pageshow', this.onPageShow.bind(this));

    if (this.html.classList.contains('clap-ferme')) {
      this.ouvrir();
    }
  }

  setOptions() {
    if ('fermeture' in this.element.dataset) {
      this.options.fermeture = parseInt(this.element.dataset.fermeture);
    }
  }

  //Fermeture

  onClick(event) {
    if (event.defaultPrevented || event.button !== 0) return;
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) {
      return;
    }

    const lien = event.target.closest('a');
    if (!lien || !this.estInterne(lien)) return;

    event.preventDefault();
    this.fermer(lien.href);
  }

  estInterne(lien) {
    const href = lien.getAttribute('href');

    if (!href || href.startsWith('#')) return false;
    if (lien.target === '_blank' || lien.hasAttribute('download')) {
      return false;
    }
    if (lien.origin !== window.location.origin) return false;
    if (lien.pathname === window.location.pathname && lien.hash) return false;

    return true;
  }

  fermer(url) {
    if (this.enCours) return;
    this.enCours = true;

    this.infos = { titre: 'Miro Leblanc', scene: 'Portfolio' };
    this.afficherInfos();
    this.chargerInfos(url);

    this.html.classList.add('clap-fermeture');

    setTimeout(() => {
      try {
        sessionStorage.setItem('clap', JSON.stringify(this.infos));
      } catch (e) {}

      window.location.href = url;
    }, this.options.fermeture);
  }

  chargerInfos(url) {
    fetch(url)
      .then((reponse) => reponse.text())
      .then((texte) => {
        const page = new DOMParser().parseFromString(texte, 'text/html');
        const surtitre = page.querySelector('.hero .surtitre');

        this.infos = {
          titre: page.title.split(' — ')[0] || this.infos.titre,
          scene: surtitre ? surtitre.textContent.trim() : 'Accueil',
        };
        this.afficherInfos();
      })
      .catch(() => {});
  }

  afficherInfos() {
    this.html.style.setProperty('--clap-titre', JSON.stringify(this.infos.titre));
    this.html.style.setProperty('--clap-scene', JSON.stringify(this.infos.scene));
  }

  //Ouverture

  ouvrir() {
    setTimeout(() => {
      this.html.classList.add('clap-ouverture');
      this.html.classList.remove('clap-ferme');

      setTimeout(() => {
        this.html.classList.remove('clap-ouverture');
      }, this.options.ouverture);
    }, this.options.pause);
  }

  onPageShow(event) {
    if (!event.persisted) return;

    this.enCours = false;
    this.html.classList.remove('clap-fermeture', 'clap-ferme');
  }
}
