import { gsap } from 'gsap';

export default class Timecode {
  constructor(element) {
    this.element = element;
    this.options = {
      mode: 'horloge',
      images: 24,
      duree: 1.2,
      ease: 'expo.out',
      attente: false,
    };
    this.debut = performance.now();
    this.texte = '';

    this.init();
  }

  init() {
    this.setOptions();

    if (this.options.mode === 'compteur') {
      this.initCompteurs();
      return;
    }

    this.update = this.update.bind(this);
    document.addEventListener('intro:rec', this.onRec.bind(this));

    if (!this.options.attente) {
      requestAnimationFrame(this.update);
    }
  }

  setOptions() {
    if ('mode' in this.element.dataset) {
      this.options.mode = this.element.dataset.mode;
    }
    if ('images' in this.element.dataset) {
      this.options.images = parseInt(this.element.dataset.images);
    }
    if ('duree' in this.element.dataset) {
      this.options.duree = parseFloat(this.element.dataset.duree);
    }
    if ('attente' in this.element.dataset) {
      this.options.attente = true;
    }
  }

  //Horloge

  // REC de l'intro : tous les timecodes repartent de 00:00:00 au même moment
  onRec(event) {
    this.debut = event.detail.debut;

    if (this.options.attente) {
      this.options.attente = false;
      requestAnimationFrame(this.update);
    }
  }

  update(temps) {
    if (!this.element.isConnected) return; // élément retiré de la page (fin de l'intro)

    const ecoule = Math.max(0, (temps - this.debut) / 1000);

    const minutes = Math.floor(ecoule / 60) % 60;
    const secondes = Math.floor(ecoule) % 60;
    const images = Math.floor((ecoule % 1) * this.options.images);

    const texte = [minutes, secondes, images]
      .map((nombre) => String(nombre).padStart(2, '0'))
      .join(':');

    if (texte !== this.texte) {
      this.texte = texte;
      this.element.textContent = texte;
    }

    requestAnimationFrame(this.update);
  }

  //Compteurs

  initCompteurs() {
    const moinsAnimations = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches;
    if (moinsAnimations) return;

    const cartes = this.element.querySelectorAll('.card');

    for (let i = 0; i < cartes.length; i++) {
      const texte = cartes[i].querySelector('.pourcentage');
      const barre = cartes[i].querySelector('.remplissage');
      const nombre = texte ? texte.textContent.match(/(\d+)\s*%/) : null;
      if (!barre || !nombre) continue;

      const compteur = { valeur: 0, cible: parseInt(nombre[1]), texte: texte };
      this.afficher(compteur);
      barre.addEventListener(
        'transitionstart',
        this.onStart.bind(this, compteur),
      );
    }
  }

  onStart(compteur, event) {
    if (event.propertyName !== 'transform') return;

    gsap.to(compteur, {
      valeur: compteur.cible,
      duration: this.options.duree,
      ease: this.options.ease,
      onUpdate: this.afficher.bind(this, compteur),
    });
  }

  afficher(compteur) {
    const nombre = String(Math.round(compteur.valeur)).padStart(2, '0');
    compteur.texte.textContent = `00:${nombre} %`;
  }
}
