const INTRO_SECONDS = 1.4;
const STYLES = { lines: 0, dashed: 1, dots: 2, crosses: 3 };

const FALLOFF_CURVES = {
  linear: (t) => t,
  smooth: (t) => t * t * (3 - 2 * t),
  sharp: (t) => t * t * t,
};

const VERTEX = `#version 300 es
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}`;

const FRAGMENT = `#version 300 es
precision highp float;
precision highp int;

uniform vec2 uResolution;
uniform vec2 uOffset;
uniform float uCellSize;
uniform sampler2D uState;
uniform ivec2 uCells;
uniform vec3 uColor;
uniform vec3 uGridColor;
uniform float uLineWidth;
uniform float uMaxOpacity;
uniform float uFillOpacity;
uniform float uGridOpacity;
uniform float uCellRadius;
uniform float uCellGap;
uniform int uGridStyle;
uniform vec2 uMouse;
uniform float uRadius;
uniform float uSpotlight;
uniform float uPresence;
uniform vec2 uEdgeFade;
uniform float uReveal;
uniform float uScroll;
uniform vec2 uFull;

out vec4 outColor;

float level(vec2 cell) {
  if (cell.x < 0.0 || cell.y < 0.0 || cell.x >= float(uCells.x) || cell.y >= float(uCells.y)) return 0.0;
  float v = texelFetch(uState, ivec2(cell), 0).r;
  return v * v * (3.0 - 2.0 * v);
}

float line(float d, float width) {
  float w = max(width, 1.0);
  return clamp(w * 0.5 + 0.5 - d, 0.0, 1.0) * (width / w);
}

float roundBox(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

void main() {
  vec2 pos = vec2(gl_FragCoord.x, uResolution.y - gl_FragCoord.y) + vec2(0.0, uScroll);
  vec2 g = (pos - uOffset) / uCellSize;
  vec2 cell = floor(g);
  vec2 f = g - cell;
  vec2 edge = min(f, 1.0 - f) * uCellSize;

  float vx = line(edge.x, uLineWidth);
  float vy = line(edge.y, uLineWidth);
  if (uGridStyle == 1) {
    float dash = uCellSize / 6.0;
    vx *= step(0.5, fract((pos.y - uOffset.y) / dash + 0.25));
    vy *= step(0.5, fract((pos.x - uOffset.x) / dash + 0.25));
  } else if (uGridStyle == 2) {
    float r = max(uLineWidth * 1.25, 1.2);
    float d = length(edge);
    vx = clamp(r + 0.5 - d, 0.0, 1.0);
    vy = 0.0;
  } else if (uGridStyle == 3) {
    float arm = uCellSize * 0.1 + uLineWidth;
    vx *= step(edge.y, arm);
    vy *= step(edge.x, arm);
  }
  float mark = max(vx, vy);

  vec2 toMouse = pos - uMouse;
  float spot = exp(-dot(toMouse, toMouse) / max(uRadius * uRadius, 1.0) * 1.6) * uSpotlight * uPresence;

  vec2 center = uFull * 0.5;
  float reach = length(center);
  float shown = smoothstep(uReveal * (reach + uCellSize * 2.0), uReveal * (reach + uCellSize * 2.0) - uCellSize * 2.0, length(pos - center));
  shown = uReveal >= 1.0 ? 1.0 : shown;

  float fade = 1.0;
  if (uEdgeFade.x > 0.0 || uEdgeFade.y > 0.0) {
    vec2 norm = pos / uFull;
    vec2 ef = max(uEdgeFade, vec2(0.0001));
    vec2 a = clamp(norm / ef, 0.0, 1.0);
    vec2 b = clamp((1.0 - norm) / ef, 0.0, 1.0);
    vec2 sa = a * a * a * (a * (a * 6.0 - 15.0) + 10.0);
    vec2 sb = b * b * b * (b * (b * 6.0 - 15.0) + 10.0);
    fade = sa.x * sa.y * sb.x * sb.y;
  }

  float own = level(cell);
  float gridAlpha = mark * min(uGridOpacity + spot * 0.45, 1.0) * fade * shown;
  float litAlpha = 0.0;
  float fillAlpha = 0.0;

  if (uCellGap <= 0.0 && uCellRadius <= 0.0) {
    vec2 side = step(0.5, f) * 2.0 - 1.0;
    float nx = level(cell + vec2(side.x, 0.0));
    float ny = level(cell + vec2(0.0, side.y));
    float nc = level(cell + side);
    float ex = max(own, nx);
    float ey = max(own, ny);
    float joint = max(max(ex, ey), nc);
    float lit;
    if (uGridStyle == 2) lit = vx * joint;
    else if (uGridStyle == 3) lit = max(vx * (edge.y < uLineWidth ? joint : ex), vy * (edge.x < uLineWidth ? joint : ey));
    else lit = max(vx * (edge.y < uLineWidth ? joint : ex), vy * (edge.x < uLineWidth ? joint : ey));
    litAlpha = lit * uMaxOpacity;
    fillAlpha = own * uFillOpacity;
  } else if (own > 0.0) {
    vec2 local = (f - 0.5) * uCellSize;
    float halfSize = uCellSize * 0.5 - max(uCellGap, 0.0);
    float radius = min(uCellRadius, halfSize);
    float sd = roundBox(local, vec2(halfSize), radius);
    float inside = clamp(0.5 - sd, 0.0, 1.0);
    float border = line(abs(sd + uLineWidth * 0.5), uLineWidth) * inside;
    litAlpha = border * own * uMaxOpacity;
    fillAlpha = inside * own * uFillOpacity;
  }
  litAlpha *= fade;
  fillAlpha *= fade;

  float cellAlpha = clamp(max(litAlpha, fillAlpha), 0.0, 1.0);
  float alpha = cellAlpha + gridAlpha * (1.0 - cellAlpha);
  vec3 premul = uColor * cellAlpha + uGridColor * gridAlpha * (1.0 - cellAlpha);
  outColor = vec4(premul, alpha);
}`;

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

export default class CursorGrid {
  constructor(element) {
    this.element = element;
    this.container = this.element.parentElement;
    this.options = {
      cellSize: 65,
      color: '#C9432B',
      gridColor: '#ffffff',
      radius: 100,
      falloff: 'smooth',
      highlight: 'area',
      holdTime: 200,
      fadeDuration: 350,
      lineWidth: 0.8,
      maxOpacity: 1,
      fillOpacity: 0,
      gridOpacity: 0,
      gridStyle: 'lines',
      cellRadius: 0,
      cellGap: 0,
      spotlight: 0.6,
      clickPulse: true,
      pulseSpeed: 850,
      ambient: 0,
      edgeFade: 0.2,
      edgeFadeHauteur: 150,
      intro: false,
    };

    this.view = { width: 1, height: 1, ratio: 1, cellSize: 0 };
    this.grid = { cols: 0, rows: 0, offX: 0, offY: 0 };
    this.pointer = { x: 0, y: 0, inside: false };
    this.mouse = { x: 0, y: 0 };
    this.pulses = [];
    this.levels = new Float32Array(0);
    this.waves = new Float32Array(0);
    this.targets = new Float32Array(0);
    this.touched = new Float32Array(0);
    this.pixels = new Uint8Array(0);
    this.presence = 0;
    this.clock = 0;
    this.raf = 0;
    this.last = 0;
    this.visible = true;
    this.dirty = true;

    this.init();
  }

  init() {
    this.setOptions();

    this.gl = this.element.getContext('webgl2', {
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      depth: false,
      stencil: false,
    });
    if (!this.gl || !this.lier()) {
      this.element.remove();
      return;
    }

    this.reduit = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.introClock = this.options.intro && !this.reduit ? 0 : 1;
    this.initTexture();

    this.frame = this.frame.bind(this);
    window.addEventListener('pointermove', this.onPointerMove.bind(this), {
      passive: true,
    });
    window.addEventListener('pointerdown', this.onPointerDown.bind(this), {
      passive: true,
    });
    document.documentElement.addEventListener(
      'pointerleave',
      this.onPointerLeave.bind(this),
    );
    document.addEventListener('visibilitychange', this.wake.bind(this));
    window.addEventListener('scroll', this.onScroll.bind(this), {
      passive: true,
    });

    const redimension = new ResizeObserver(() => {
      this.rebuild();
      this.draw();
      this.wake();
    });
    redimension.observe(this.container);
    redimension.observe(this.element);

    new IntersectionObserver((entries) => {
      this.visible = entries.some((entry) => entry.isIntersecting);
      if (this.visible) this.wake();
    }).observe(this.container);

    this.rebuild();
    if (this.introClock < 1) {
      this.pulses.push({
        x: this.view.width / 2,
        y: this.view.height / 2,
        t0: 0.15,
        strength: 0.6,
      });
    }
    this.draw();
    this.wake();
  }

  setOptions() {
    const o = this.options;
    o.cellSize = Math.max(8, o.cellSize);
    o.radius = Math.max(1, o.radius);
    o.holdTime = Math.max(0, o.holdTime);
    o.fadeDuration = Math.max(16, o.fadeDuration);
    o.lineWidth = Math.max(0.25, o.lineWidth);
    o.maxOpacity = clamp(o.maxOpacity, 0, 1);
    o.fillOpacity = clamp(o.fillOpacity, 0, 1);
    o.gridOpacity = clamp(o.gridOpacity, 0, 1);
    o.gridStyle = STYLES[o.gridStyle] ?? 0;
    o.cellRadius = Math.max(0, o.cellRadius);
    o.cellGap = Math.max(0, o.cellGap);
    o.spotlight = clamp(o.spotlight, 0, 1);
    o.pulseSpeed = Math.max(1, o.pulseSpeed);
    o.ambient = clamp(o.ambient, 0, 1);
    o.edgeFade = clamp(o.edgeFade, 0, 0.5);
    o.colorRgb = this.couleur(o.color);
    o.gridColorRgb = this.couleur(o.gridColor);
  }

  //WebGL

  compiler(type, source) {
    const gl = this.gl;
    const shader = gl.createShader(type);
    if (!shader) return null;
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
    gl.deleteShader(shader);
    return null;
  }

  lier() {
    const gl = this.gl;
    const vertex = this.compiler(gl.VERTEX_SHADER, VERTEX);
    const fragment = this.compiler(gl.FRAGMENT_SHADER, FRAGMENT);
    const program = gl.createProgram();
    if (!vertex || !fragment || !program) return false;

    gl.attachShader(program, vertex);
    gl.attachShader(program, fragment);
    gl.linkProgram(program);
    gl.deleteShader(vertex);
    gl.deleteShader(fragment);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      gl.deleteProgram(program);
      return false;
    }

    this.u = {};
    const count = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
    for (let i = 0; i < count; i++) {
      const info = gl.getActiveUniform(program, i);
      if (info) this.u[info.name] = gl.getUniformLocation(program, info.name);
    }
    this.program = program;
    this.vao = gl.createVertexArray();
    return true;
  }

  initTexture() {
    const gl = this.gl;
    this.stateTexture = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, this.stateTexture);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
  }

  couleur(hex) {
    let h = String(hex || '#ffffff')
      .replace('#', '')
      .trim();
    if (h.length === 3 || h.length === 4) {
      h = h
        .slice(0, 3)
        .split('')
        .map((c) => c + c)
        .join('');
    }
    const num = parseInt(h.slice(0, 6), 16);
    if (Number.isNaN(num)) return [1, 1, 1];
    return [
      ((num >> 16) & 255) / 255,
      ((num >> 8) & 255) / 255,
      (num & 255) / 255,
    ];
  }

  //Grille

  rebuild() {
    const gl = this.gl;
    const view = this.view;
    const grid = this.grid;
    const size = this.options.cellSize;

    view.width = Math.max(1, this.container.clientWidth);
    view.height = Math.max(1, this.container.clientHeight);
    view.ratio = Math.min(window.devicePixelRatio || 1, 2);
    this.element.width = Math.max(
      1,
      Math.round(this.element.clientWidth * view.ratio),
    );
    this.element.height = Math.max(
      1,
      Math.round(this.element.clientHeight * view.ratio),
    );

    const cols = Math.ceil(view.width / size) + 1;
    const rows = Math.ceil(view.height / size) + 1;
    const resized =
      cols !== grid.cols || rows !== grid.rows || size !== view.cellSize;
    grid.cols = cols;
    grid.rows = rows;
    grid.offX = (view.width - cols * size) / 2;
    grid.offY = (view.height - rows * size) / 2;
    view.cellSize = size;

    if (resized) {
      this.levels = new Float32Array(cols * rows);
      this.waves = new Float32Array(cols * rows);
      this.targets = new Float32Array(cols * rows);
      this.touched = new Float32Array(cols * rows).fill(-1e9);
      this.pixels = new Uint8Array(cols * rows);
      gl.bindTexture(gl.TEXTURE_2D, this.stateTexture);
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.R8,
        cols,
        rows,
        0,
        gl.RED,
        gl.UNSIGNED_BYTE,
        this.pixels,
      );
    }
    this.dirty = true;
  }

  light(index, value) {
    if (value > this.targets[index]) this.targets[index] = value;
    this.touched[index] = this.clock;
  }

  energize(x, y) {
    const o = this.options;
    const grid = this.grid;
    const size = o.cellSize;

    if (o.highlight === 'cell') {
      const col = Math.floor((x - grid.offX) / size);
      const row = Math.floor((y - grid.offY) / size);
      if (col >= 0 && row >= 0 && col < grid.cols && row < grid.rows) {
        this.light(row * grid.cols + col, 1);
      }
      return;
    }

    const r = o.radius;
    const ease = FALLOFF_CURVES[o.falloff] ?? FALLOFF_CURVES.linear;
    const minCol = Math.max(0, Math.floor((x - r - grid.offX) / size));
    const maxCol = Math.min(grid.cols - 1, Math.floor((x + r - grid.offX) / size));
    const minRow = Math.max(0, Math.floor((y - r - grid.offY) / size));
    const maxRow = Math.min(grid.rows - 1, Math.floor((y + r - grid.offY) / size));

    for (let row = minRow; row <= maxRow; row++) {
      for (let col = minCol; col <= maxCol; col++) {
        const cx = grid.offX + col * size + size / 2;
        const cy = grid.offY + row * size + size / 2;
        const dist = Math.hypot(cx - x, cy - y);
        if (dist > r) continue;
        const value = ease(1 - dist / r);
        if (value > 0) this.light(row * grid.cols + col, value);
      }
    }
  }

  sweepPulses() {
    const o = this.options;
    const grid = this.grid;
    const size = o.cellSize;
    const ahead = size * 0.6;
    const behind = size * 1.4;
    const far = Math.hypot(this.view.width, this.view.height);
    this.waves.fill(0);

    for (let k = this.pulses.length - 1; k >= 0; k--) {
      const pulse = this.pulses[k];
      const ringR = (this.clock - pulse.t0) * o.pulseSpeed;
      if (ringR - behind * 2 > far) {
        this.pulses.splice(k, 1);
        continue;
      }
      if (ringR < 0) continue;

      const envelope =
        pulse.strength * Math.pow(Math.max(0, 1 - ringR / (far + behind)), 0.6);
      const outer = ringR + ahead * 2;
      const minCol = Math.max(0, Math.floor((pulse.x - outer - grid.offX) / size));
      const maxCol = Math.min(grid.cols - 1, Math.floor((pulse.x + outer - grid.offX) / size));
      const minRow = Math.max(0, Math.floor((pulse.y - outer - grid.offY) / size));
      const maxRow = Math.min(grid.rows - 1, Math.floor((pulse.y + outer - grid.offY) / size));

      for (let row = minRow; row <= maxRow; row++) {
        for (let col = minCol; col <= maxCol; col++) {
          const cx = grid.offX + col * size + size / 2;
          const cy = grid.offY + row * size + size / 2;
          const off = Math.hypot(cx - pulse.x, cy - pulse.y) - ringR;
          if (off > ahead * 2 || off < -behind * 2) continue;
          const t = off > 0 ? off / ahead : off / behind;
          const value = envelope * Math.exp(-t * t);
          const index = row * grid.cols + col;
          if (value > this.waves[index]) this.waves[index] = value;
        }
      }
    }
    this.dirty = true;
  }

  draw() {
    const gl = this.gl;
    const o = this.options;
    const u = this.u;
    const ratio = this.view.ratio;

    gl.viewport(0, 0, this.element.width, this.element.height);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.useProgram(this.program);
    gl.bindVertexArray(this.vao);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.stateTexture);

    if (this.dirty) {
      for (let i = 0; i < this.levels.length; i++) {
        this.pixels[i] = Math.round(
          clamp(Math.max(this.levels[i], this.waves[i]), 0, 1) * 255,
        );
      }
      gl.texSubImage2D(
        gl.TEXTURE_2D,
        0,
        0,
        0,
        this.grid.cols,
        this.grid.rows,
        gl.RED,
        gl.UNSIGNED_BYTE,
        this.pixels,
      );
      this.dirty = false;
    }

    const lineDevice = o.lineWidth * ratio;
    const snap = Math.round(lineDevice) % 2 === 1 ? 0.5 : 0;
    gl.uniform1i(u.uState, 0);
    gl.uniform2f(u.uResolution, this.element.width, this.element.height);
    gl.uniform2f(
      u.uOffset,
      Math.round(this.grid.offX * ratio) + snap,
      Math.round(this.grid.offY * ratio) + snap,
    );
    gl.uniform1f(u.uCellSize, o.cellSize * ratio);
    gl.uniform2i(u.uCells, this.grid.cols, this.grid.rows);
    gl.uniform3fv(u.uColor, o.colorRgb);
    gl.uniform3fv(u.uGridColor, o.gridColorRgb);
    gl.uniform1f(u.uLineWidth, lineDevice);
    gl.uniform1f(u.uMaxOpacity, o.maxOpacity);
    gl.uniform1f(u.uFillOpacity, o.fillOpacity);
    gl.uniform1f(u.uGridOpacity, o.gridOpacity);
    gl.uniform1f(u.uCellRadius, o.cellRadius * ratio);
    gl.uniform1f(u.uCellGap, o.cellGap * ratio);
    gl.uniform1i(u.uGridStyle, o.gridStyle);
    gl.uniform2f(u.uMouse, this.mouse.x * ratio, this.mouse.y * ratio);
    gl.uniform1f(u.uRadius, o.radius * ratio);
    gl.uniform1f(u.uSpotlight, o.spotlight);
    gl.uniform1f(u.uPresence, this.presence);
    const haut =
      this.element.getBoundingClientRect().top -
      this.container.getBoundingClientRect().top;
    gl.uniform1f(u.uScroll, haut * ratio);
    gl.uniform2f(u.uFull, this.view.width * ratio, this.view.height * ratio);
    gl.uniform2f(
      u.uEdgeFade,
      o.edgeFade,
      Math.min(o.edgeFade, o.edgeFadeHauteur / this.view.height),
    );
    gl.uniform1f(
      u.uReveal,
      this.introClock >= 1 ? 1 : 1 - Math.pow(1 - this.introClock, 2.2),
    );
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.bindVertexArray(null);
  }

  //Animation

  frame(now) {
    this.raf = 0;
    if (!this.visible || document.hidden) return;

    const o = this.options;
    const dt = this.last ? clamp((now - this.last) / 1000, 0, 1 / 20) : 1 / 60;
    this.last = now;
    this.clock += dt;
    if (this.introClock < 1) {
      this.introClock = Math.min(1, this.introClock + dt / INTRO_SECONDS);
    }

    const follow = 1 - Math.exp(-dt / 0.07);
    this.mouse.x += (this.pointer.x - this.mouse.x) * follow;
    this.mouse.y += (this.pointer.y - this.mouse.y) * follow;
    const presenceGoal = this.pointer.inside ? 1 : 0;
    this.presence +=
      (presenceGoal - this.presence) * (1 - Math.exp(-dt / 0.25));

    if (o.ambient > 0 && !this.reduit && this.levels.length) {
      const chance = o.ambient * dt * this.levels.length * 0.04;
      let spawns = Math.floor(chance) + (Math.random() < chance % 1 ? 1 : 0);
      while (spawns-- > 0) {
        this.light(
          Math.floor(Math.random() * this.levels.length),
          0.25 + Math.random() * 0.45,
        );
      }
    }

    if (this.pulses.length) {
      this.sweepPulses();
    } else if (this.waves.length && this.waves.some((value) => value > 0)) {
      this.waves.fill(0);
      this.dirty = true;
    }

    const holdSeconds = o.holdTime / 1000;
    const fadeStep = dt / (o.fadeDuration / 1000);
    const attack = 1 - Math.exp(-dt / 0.045);
    let active =
      this.pulses.length > 0 ||
      this.introClock < 1 ||
      Math.abs(this.presence - presenceGoal) > 0.002;

    for (let i = 0; i < this.levels.length; i++) {
      let target = this.targets[i];
      if (target <= 0 && this.levels[i] <= 0) continue;
      if (this.clock - this.touched[i] > holdSeconds) {
        target = Math.max(0, target - fadeStep);
      }
      this.targets[i] = target;
      const before = this.levels[i];
      const next = target > before ? before + (target - before) * attack : target;
      this.levels[i] = next < 0.002 ? 0 : next;
      if (this.levels[i] !== before) this.dirty = true;
      if (this.levels[i] > 0 || this.targets[i] > 0) active = true;
    }

    if (
      Math.abs(this.mouse.x - this.pointer.x) +
        Math.abs(this.mouse.y - this.pointer.y) >
        0.05 &&
      this.presence > 0.002
    ) {
      active = true;
    }
    if (o.ambient > 0 && !this.reduit) active = true;

    this.draw();
    if (active) this.raf = requestAnimationFrame(this.frame);
  }

  wake() {
    if (!this.raf && this.visible && !document.hidden) {
      this.last = 0;
      this.raf = requestAnimationFrame(this.frame);
    }
  }

  //Souris

  locate(event) {
    const rect = this.container.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    return {
      x,
      y,
      inside: x >= 0 && y >= 0 && x <= rect.width && y <= rect.height,
    };
  }

  onScroll() {
    if (!this.visible) return;

    if (this.dernier) {
      this.onPointerMove(this.dernier);
    }
    this.dirty = true;

    if (!this.rafScroll) {
      this.rafScroll = requestAnimationFrame(() => {
        this.rafScroll = 0;
        this.draw();
        this.wake();
      });
    }
  }

  onPointerMove(event) {
    this.dernier = { clientX: event.clientX, clientY: event.clientY };
    const { x, y, inside } = this.locate(event);
    const was = this.pointer.inside;
    this.pointer.inside = inside;

    if (!inside) {
      if (was) this.wake();
      return;
    }

    this.pointer.x = x;
    this.pointer.y = y;
    if (!was) {
      this.mouse.x = x;
      this.mouse.y = y;
    }
    this.energize(x, y);
    this.wake();
  }

  onPointerDown(event) {
    const { x, y, inside } = this.locate(event);
    if (!inside || !this.options.clickPulse || this.reduit) return;

    this.pulses.push({ x, y, t0: this.clock, strength: 1 });
    this.wake();
  }

  onPointerLeave() {
    this.pointer.inside = false;
    this.wake();
  }
}
