export default class Header {
  constructor(element) {
    this.element = element;
    this.options = {
      compactAt: 0.5,
    };
    this.scrollPosition = 0;
    this.lastScrollPosition = 0;
    this.html = document.documentElement;

    this.init();
    this.initNavMobile();
    this.initSections();
    this.initAncres();
  }

  init() {
    this.setOptions();

    window.addEventListener('scroll', this.onScroll.bind(this));
    this.onScroll();
  }

  setOptions() {}

  onScroll() {
    this.lastScrollPosition = this.scrollPosition;
    this.scrollPosition = document.scrollingElement.scrollTop;

    this.setHeaderState();
    this.setDirections();
    this.setActiveSection();
  }

  setHeaderState() {
    const isCompact =
      this.scrollPosition > window.innerHeight * this.options.compactAt;
    this.html.classList.toggle('nav-is-compact', isCompact);
  }

  setDirections() {
    if (this.scrollPosition >= this.lastScrollPosition) {
      //scroll vers le bas
      this.html.classList.add('is-scrolling-down');
      this.html.classList.remove('is-scrolling-up');
    } else {
      //scroll vers le haut
      this.html.classList.remove('is-scrolling-down');
      this.html.classList.add('is-scrolling-up');
    }
  }

  initSections() {
    this.sections = [];
    const links = this.element.querySelectorAll('.nav__link');

    for (let i = 0; i < links.length; i++) {
      const id = links[i].getAttribute('href').split('#')[1];
      const section = id ? document.getElementById(id) : null;

      if (section) {
        this.sections.push({ section: section, item: links[i].parentElement });
      }
    }

    this.setActiveSection();
  }

  setActiveSection() {
    if (!this.sections) return;

    const middle = window.innerHeight / 2;
    let active = null;

    for (let i = 0; i < this.sections.length; i++) {
      if (this.sections[i].section.getBoundingClientRect().top <= middle) {
        active = this.sections[i];
      }
    }

    for (let i = 0; i < this.sections.length; i++) {
      this.sections[i].item.classList.toggle(
        'is-active',
        this.sections[i] === active,
      );
    }
  }

  initNavMobile() {
    this.toggle = this.element.querySelector('.js-toggle');
    if (!this.toggle) return;
    this.toggle.addEventListener('click', this.onToggleNav.bind(this));
    document.addEventListener('keydown', this.onKeyNav.bind(this));

    const liens = this.element.querySelectorAll('.nav__link');
    for (let i = 0; i < liens.length; i++) {
      liens[i].addEventListener('click', this.fermerNav.bind(this));
    }
  }

  onToggleNav(event) {
    this.html.classList.toggle('nav-is-active');

    const ouvert = this.html.classList.contains('nav-is-active');
    this.toggle.setAttribute('aria-expanded', ouvert);
    this.toggle.setAttribute(
      'aria-label',
      ouvert ? 'Fermer le menu' : 'Ouvrir le menu',
    );
  }

  fermerNav() {
    if (!this.html.classList.contains('nav-is-active')) return;
    this.onToggleNav();
  }

  onKeyNav(event) {
    if (event.key !== 'Escape') return;
    if (!this.html.classList.contains('nav-is-active')) return;

    this.fermerNav();
    this.toggle.focus();
  }

  //Liens vers les sections

  initAncres() {
    history.scrollRestoration = 'manual';

    const liens = document.querySelectorAll('a[href*="#"]');
    for (let i = 0; i < liens.length; i++) {
      liens[i].addEventListener('click', this.onClickAncre.bind(this));
    }

    // arrivée depuis une autre page (ex. index.html#projets) : on attend que GSAP
    // ait fini de calculer les sections figées, puis on se place sur la section
    if (window.location.hash) {
      window.addEventListener('load', () => {
        setTimeout(() => this.allerA(window.location.hash, 'auto'), 100);
      });
    }
  }

  // si la section est sur la page actuelle : on défile en douceur au lieu de recharger la page
  onClickAncre(event) {
    const hash = event.currentTarget.hash;
    if (!hash || !document.querySelector(hash)) return;

    event.preventDefault();
    this.allerA(hash, 'smooth');
  }

  allerA(hash, comportement) {
    const section = document.querySelector(hash);
    if (!section) return;

    const haut = section.getBoundingClientRect().top + window.scrollY;
    window.scrollTo({ top: haut, behavior: comportement });
  }
}
