export default class CopierCourriel {
  constructor(element) {
    this.element = element;
    this.options = {
      duree: 2000,
    };
    this.courriel = this.element.getAttribute('href').replace('mailto:', '');

    this.init();
  }

  init() {
    this.setOptions();

    this.annonce = document.createElement('span');
    this.annonce.className = 'courriel__annonce';
    this.annonce.setAttribute('aria-live', 'polite');
    document.body.appendChild(this.annonce);

    this.element.setAttribute('title', 'Copier le courriel');
    this.element.addEventListener('click', this.onClick.bind(this));
  }

  setOptions() {
    if ('duree' in this.element.dataset) {
      this.options.duree = parseInt(this.element.dataset.duree);
    }
  }

  onClick(event) {
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) {
      return;
    }

    event.preventDefault();
    this.copier()
      .then(this.confirmer.bind(this))
      .catch(() => {
        window.location.href = this.element.href;
      });
  }

  copier() {
    if (navigator.clipboard && window.isSecureContext) {
      return navigator.clipboard.writeText(this.courriel);
    }

    return new Promise((resolve, reject) => {
      const champ = document.createElement('textarea');
      champ.value = this.courriel;
      champ.setAttribute('readonly', '');
      champ.style.position = 'fixed';
      champ.style.opacity = '0';
      document.body.appendChild(champ);
      champ.select();
      const reussi = document.execCommand('copy');
      champ.remove();

      if (reussi) {
        resolve();
      } else {
        reject();
      }
    });
  }

  confirmer() {
    this.element.classList.add('is-copie');
    this.annonce.textContent = 'Courriel copié';

    clearTimeout(this.minuterie);
    this.minuterie = setTimeout(() => {
      this.element.classList.remove('is-copie');
      this.annonce.textContent = '';
    }, this.options.duree);
  }
}
